response.output:
{
  "world_id": "wld_glass_tide",
  "name": "The Listening Lagoon",
  "description": "In a sunlit coastal city, the lagoon's tide turns waterwheels, lifts cargo, and carries freshwater through a web of canals. Junior tide-warden Neri discovers that silt is sealing the gates weeks early, just as the guilds prepare for their glassblowing season. The furnaces use concentrated sunlight, and their work gives the city its famed mirrored roofs—but the season's draw on the lagoon's water and labor could leave the gates unattended. A hopeful solarpunk world of living infrastructure, ingenious craft, and civic cooperation, where the city must decide what prosperity means before the tide fails.",
  "locations": [
    {
      "id": "loc_lagoon_gates",
      "name": "The Listening Gates",
      "description": "A chain of tidal sluices whose hollow ceramic fins hum at different pitches as water passes. Wardens read their changing notes to track flow and hear the first warning signs of silt."
    },
    {
      "id": "loc_sunworks",
      "name": "The Sunworks",
      "description": "A stepped terrace of mirrored heliostats and glass furnaces. Sunlight supplies the heat; seasonal crews shape lenses, roof tiles, and delicate canal gauges."
    },
    {
      "id": "loc_reedward",
      "name": "Reedward Commons",
      "description": "A floating neighborhood of reed gardens, algae ponds, and shared waterwheels. Its residents know the lagoon's small currents and rely on the gates for clean water."
    },
    {
      "id": "loc_silt_archive",
      "name": "The Silt Archive",
      "description": "A tide-marked hall where clay tablets record gate depths, harvest cycles, and flood levels. Recent measurements show the lagoon bed rising faster than the official forecasts."
    }
  ],
  "factions": [
    {
      "id": "fac_tidewardens",
      "name": "Tidewardens",
      "description": "Canal keepers who maintain the gates and publish flow readings. They trust long records and direct observation, but have little authority over guild schedules.",
      "location_ids": ["loc_lagoon_gates", "loc_silt_archive"]
    },
    {
      "id": "fac_glassguild",
      "name": "Glass Guild",
      "description": "Makers and merchants whose annual season sustains the city's craft economy. They use solar furnaces and argue that a shortened season would imperil apprentices and shared workshops.",
      "location_ids": ["loc_sunworks"]
    },
    {
      "id": "fac_reedward",
      "name": "Reedward Assembly",
      "description": "Residents and growers who manage floating gardens and communal waterwheels. They favor an immediate pause to protect drinking water, yet depend on the guild's income for repairs.",
      "location_ids": ["loc_reedward"]
    },
    {
      "id": "fac_measurekeepers",
      "name": "Measurekeepers",
      "description": "Archivists who compare old tide marks with new readings. Their custom forbids altering a public record, though some fear that releasing uncertain measurements will provoke panic.",
      "location_ids": ["loc_silt_archive"]
    }
  ],
  "rules": [
    {
      "id": "rul_tidal_work",
      "statement": "The lagoon's rise and fall supplies the mechanical power for canal lifts, mills, and cargo platforms.",
      "category": "physics"
    },
    {
      "id": "rul_solar_heat",
      "statement": "Glass furnaces are heated by concentrated sunlight, and no combustion engines or fossil fuels are used anywhere.",
      "category": "technology"
    },
    {
      "id": "rul_gate_hum",
      "statement": "The ceramic fins of the gates change pitch with water pressure and silt depth, making their song a practical warning system.",
      "category": "technology"
    },
    {
      "id": "rul_shared_water",
      "statement": "During a declared shortage, drinking water and gate maintenance take priority over private production allotments.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_gates",
      "name": "The First Listening",
      "description": "Canal builders fitted the sluices with hollow ceramic fins, turning routine gate inspections into a shared craft of listening and measurement.",
      "era": "Founding years",
      "location_ids": ["loc_lagoon_gates"]
    },
    {
      "id": "evt_sunworks_charter",
      "name": "The Mirrored Charter",
      "description": "After a season of scarce fuelwood, the guilds and wardens agreed to power the glassworks with sunlight and reserve a share of each season's labor for canal upkeep.",
      "era": "Three generations ago",
      "location_ids": ["loc_sunworks", "loc_lagoon_gates"]
    },
    {
      "id": "evt_rising_bed",
      "name": "The Unmatched Marks",
      "description": "The latest tablets show the lagoon bed rising faster than the old cycles predict. The measurements were copied faithfully, but their warning has not yet changed the guild calendar.",
      "era": "Present season",
      "location_ids": ["loc_silt_archive", "loc_reedward"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_season_or_gates",
      "name": "The Season at the Sluices",
      "description": "Tidewardens want the glass season halted so crews can clear and inspect the gates; the Glass Guild fears a lost season will break livelihoods. Both need a working lagoon, but the warning leaves little time to agree.",
      "faction_ids": ["fac_tidewardens", "fac_glassguild"]
    },
    {
      "id": "cnf_warning_and_trust",
      "name": "A Record Made Public",
      "description": "The Measurekeepers hesitate to announce uncertain forecasts without a complete explanation, while the Reedward Assembly demands action before water supplies fail. Publishing the readings may force cooperation—or deepen distrust.",
      "faction_ids": ["fac_measurekeepers", "fac_reedward"]
    }
  ]
}

