response.output:
{
  "world_id": "wld_mistveil_isles",
  "name": "The Mistveil Isles",
  "description": "Across a chain of steep, rain-bright islands, sword schools guard old paths and clan ferries cross waters veiled in silver fog. Here, a blade's honor is measured not by the bodies it leaves behind but by the promises it can make others keep. When a disowned student inherits her late master's tally-stick, she must carry it to three rival sects and summon a peace moot before their feud consumes the last crane rookeries. The stick is more than a token: its notches record debts shared by enemies, and each island's elders know a different way to read them.",
  "locations": [
    {
      "id": "loc_sedgewake",
      "name": "Sedgewake Rookery",
      "description": "A broad marsh of reed islands and black pools where the last cranes nest in alder crowns. Clan wardens mark the nesting beds with white cords; cutting one is treated as a declaration against every island."
    },
    {
      "id": "loc_ashbridge",
      "name": "Ashbridge Stair",
      "description": "A cliffside village joined by narrow stone steps and a single cedar bridge. The late master's sword school once trained here, and its sealed practice yard still bears the grooves of generations of footwork."
    },
    {
      "id": "loc_mirrorharbor",
      "name": "Mirrorwake Harbor",
      "description": "A sheltered inlet where the water reflects the sky so clearly that pilots steer by the reversed stars. Three rival sects maintain separate piers, sharing one tide bell whose silences are as carefully observed as its rings."
    },
    {
      "id": "loc_hollowbell",
      "name": "Hollow Bell Isle",
      "description": "A wind-carved island crowned by a bronze-free stone bell tower, whose hollow rock gives each spoken oath a second, softer echo. The old moot ground lies beneath it, reachable only when the ebb exposes a causeway."
    }
  ],
  "factions": [
    {
      "id": "fac_reedwardens",
      "name": "The Reedwardens",
      "description": "Marsh clans who protect the rookeries and navigate by reed knots, bird calls, and inherited water maps. They will shelter the student, but only if the moot can secure the nesting grounds.",
      "location_ids": [
        "loc_sedgewake"
      ]
    },
    {
      "id": "fac_ashbridge_school",
      "name": "Ashbridge School",
      "description": "A diminished sword school whose students prize patience and exact measure. They disowned their master's pupil after she refused to name a rival as the cause of a fatal duel.",
      "location_ids": [
        "loc_ashbridge"
      ]
    },
    {
      "id": "fac_three_piers",
      "name": "The Three Piers",
      "description": "A wary compact of three rival sects, each claiming the right to interpret the late master's tally-stick. Their leaders will attend a moot only if all receive the same challenge and none can claim precedence.",
      "location_ids": [
        "loc_mirrorharbor"
      ]
    },
    {
      "id": "fac_ebbkeepers",
      "name": "The Ebbkeepers",
      "description": "Oath witnesses who tend the old moot ground and remember which families broke its peace. They believe the tower's answering echo can expose a lie, though it cannot compel anyone to tell the truth.",
      "location_ids": [
        "loc_hollowbell"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_challenge",
      "statement": "Duels are settled by formal challenge, never ambush; an unannounced attack earns no standing in a clan's law.",
      "category": "social"
    },
    {
      "id": "rul_tally",
      "statement": "A master's tally-stick binds only those whose debts are named on it, and each notch must be witnessed by a living party to the debt.",
      "category": "social"
    },
    {
      "id": "rul_echo",
      "statement": "At Hollow Bell Isle, an oath spoken over the exposed causeway returns as an echo, but the echo reveals no truth beyond the speaker's own words.",
      "category": "metaphysics"
    },
    {
      "id": "rul_rookery",
      "statement": "During the nesting season, no clan may cut reeds or fell trees within a marked rookery without the Reedwardens' consent.",
      "category": "social"
    },
    {
      "id": "rul_tide",
      "statement": "The causeway to the old moot ground appears only at the ebb; no vessel can reach it across the surrounding reefs at high water.",
      "category": "physics"
    }
  ],
  "history": [
    {
      "id": "evt_shared_debts",
      "name": "The Master's Shared Tally",
      "description": "Years ago, the sword master settled a feud by recording obligations owed across clan lines instead of naming a victor. Each sect accepted one notch, though none agreed on what the whole tally meant.",
      "era": "Before the rookery feud",
      "location_ids": [
        "loc_ashbridge",
        "loc_mirrorharbor"
      ]
    },
    {
      "id": "evt_first_felled",
      "name": "The First Fallen Alder",
      "description": "A disputed boundary led one clan to fell an alder at the edge of the nesting marsh. The lost nests drove the Reedwardens to bar passage to both sides, turning a local quarrel into an island-wide crisis.",
      "era": "The first winter of the feud",
      "location_ids": [
        "loc_sedgewake"
      ]
    },
    {
      "id": "evt_last_lesson",
      "name": "The Last Lesson",
      "description": "Near death, the master entrusted the tally-stick to his pupil and told her that a debt carried alone becomes a weapon. The school disowned her soon after, leaving her without a teacher's protection.",
      "era": "The master's final season",
      "location_ids": [
        "loc_ashbridge"
      ]
    },
    {
      "id": "evt_moot_silence",
      "name": "Silence of the Tide Bell",
      "description": "When the Three Piers refused to ring the shared tide bell, each sect declared the others unfit to call a moot. The Ebbkeepers reopened the old ground, but its causeway will not show until the clans agree to come.",
      "era": "The present dispute",
      "location_ids": [
        "loc_mirrorharbor",
        "loc_hollowbell"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_rookery",
      "name": "The Last Nesting Ground",
      "description": "The Reedwardens demand a protected rookery, while rival clans argue over the reeds and timber that sustain their ferries and homes. Every delay in the moot risks another nesting season lost.",
      "faction_ids": [
        "fac_reedwardens",
        "fac_three_piers"
      ]
    },
    {
      "id": "cnf_tally_meaning",
      "name": "Who Owns the Notches",
      "description": "The Three Piers each claim the tally-stick proves their version of the master's old settlement. The student's missing place in the school makes her authority easy to challenge, even as her delivery is the only path to a moot.",
      "faction_ids": [
        "fac_ashbridge_school",
        "fac_three_piers"
      ]
    },
    {
      "id": "cnf_echo_oath",
      "name": "The Echo's Limit",
      "description": "The Ebbkeepers can convene witnesses, but the tower's echo cannot distinguish a true account from a carefully repeated lie. The factions must decide whether peace can rest on an oath no magic can verify.",
      "faction_ids": [
        "fac_ebbkeepers",
        "fac_three_piers"
      ]
    }
  ]
}

