response.output:
{
  "world_id": "wld_sunside_yard",
  "name": "Sunside Yard",
  "description": "At a shipyard inside Mercury's orbit, salvage rigger Mara Venn finds a hull marked scrapped still drawing power from the yard grid. Its broad solar sail is furled, its registry dead, and its power demand too steady to dismiss as instrument drift. With charter auditors inbound on a predictable transfer, Mara must trace the load and establish what the yard has kept alive—before the evidence is dismantled or the audit locks the whole berth. Sunlight is an industrial hazard, every transfer takes time, and there is no shortcut around orbital mechanics. The yard's ledger contains a stranger clue: the hull's power draw matches a missing interval in the station's decades-old thermal records.",
  "locations": [
    {
      "id": "loc_cinder_spindle",
      "name": "Cinder Spindle",
      "description": "The rotating yard hub, built around a shaded truss and armored against the glare. Its charter office controls berth access, work orders, and the master power ledger."
    },
    {
      "id": "loc_sail_cradle",
      "name": "Sail Cradle",
      "description": "An open-frame assembly berth where reflective sail film is tensioned, inspected, and tested against calibrated light. A vessel parked here must keep its attitude and orbit within tight limits."
    },
    {
      "id": "loc_ash_dock",
      "name": "Ash Dock",
      "description": "A cold salvage pocket beyond the main work ring, where condemned hulls wait for cutting crews and their remaining energy is supposed to be isolated. The disputed vessel sits under a scrapping seal."
    },
    {
      "id": "loc_shadow_vault",
      "name": "Shadow Vault",
      "description": "A buried thermal store and cable junction inside the hub's shaded spine. Its maintenance logs have a decades-long gap, though the sensors show a faint, regular exchange of heat."
    }
  ],
  "factions": [
    {
      "id": "fac_charter_office",
      "name": "Cinder Charter Office",
      "description": "The yard's contract administrators, responsible for certified mass, power use, and the coming audit. They fear that an unlogged vessel could void the yard's salvage charter.",
      "location_ids": [
        "loc_cinder_spindle"
      ]
    },
    {
      "id": "fac_riggers_union",
      "name": "Sunside Riggers' Compact",
      "description": "A practical union of riggers and sail technicians who know which work orders conceal dangerous improvisation. They want the hull investigated, but not at the cost of every worker's berth clearance.",
      "location_ids": [
        "loc_sail_cradle",
        "loc_ash_dock"
      ]
    },
    {
      "id": "fac_heatkeepers",
      "name": "Shadow Vault Keepers",
      "description": "A small maintenance crew charged with balancing the yard's heat stores. Their predecessors sealed a private circuit into the vault, and the current crew has inherited its silence along with its keys.",
      "location_ids": [
        "loc_shadow_vault",
        "loc_cinder_spindle"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_orbital_transfers",
      "statement": "Every vessel follows orbital mechanics; changing orbit costs propellant, time, or both, and no craft can make an instantaneous rendezvous.",
      "category": "physics"
    },
    {
      "id": "rul_light_delay",
      "statement": "Signals travel no faster than light, so distant ships and stations exchange messages with measurable delay.",
      "category": "physics"
    },
    {
      "id": "rul_sail_attitude",
      "statement": "A reflective sail produces useful thrust only when its orientation and illumination are controlled; a damaged or shadowed sail cannot provide reliable station-keeping.",
      "category": "technology"
    },
    {
      "id": "rul_heat_budget",
      "statement": "The yard must reject or store every unit of waste heat; unexplained power consumption eventually appears as a thermal imbalance.",
      "category": "technology"
    },
    {
      "id": "rul_charter_audit",
      "statement": "The charter requires each hull, mass transfer, and power connection to have a traceable entry; an unresolved discrepancy can suspend salvage operations.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_berths",
      "name": "First Berths Cut",
      "description": "The yard opened as a refit station for inner-system sail craft, with its shaded spine designed to buffer the sharp swings between sunlight and stored heat.",
      "era": "Founding years",
      "location_ids": [
        "loc_cinder_spindle",
        "loc_sail_cradle"
      ]
    },
    {
      "id": "evt_vault_gap",
      "name": "The Vault Interval",
      "description": "A power-balancing incident left a long blank in the Shadow Vault's maintenance archive. Officials called it a sensor failure; later crews found the junction seals newer than the record claimed.",
      "era": "Two decades before the audit",
      "location_ids": [
        "loc_shadow_vault"
      ]
    },
    {
      "id": "evt_hull_condemned",
      "name": "Condemned on Paper",
      "description": "A sail vessel was entered as scrapped and assigned to Ash Dock, but its cutting authorization was never countersigned. Its registry was closed anyway.",
      "era": "Recent cycle",
      "location_ids": [
        "loc_ash_dock",
        "loc_cinder_spindle"
      ]
    },
    {
      "id": "evt_power_anomaly",
      "name": "The Steady Draw",
      "description": "A rigger reconciling berth loads noticed a persistent current attributed to the condemned hull. Comparing it with the vault's heat traces revealed the same recurring pattern.",
      "era": "Audit approach",
      "location_ids": [
        "loc_ash_dock",
        "loc_shadow_vault"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_audit_clock",
      "name": "The Audit Clock",
      "description": "The Charter Office needs a clean ledger before auditors arrive; the Riggers' Compact needs time to inspect the hull without losing access to the berth. Any delay risks a shutdown, while any hurried declaration could erase the only evidence.",
      "faction_ids": [
        "fac_charter_office",
        "fac_riggers_union"
      ]
    },
    {
      "id": "cnf_heatkeepers_secret",
      "name": "A Circuit Kept Quiet",
      "description": "The Heatkeepers can explain the old thermal traces but risk exposing an unauthorized connection maintained across generations. The rigger needs their records; the crew must decide whether disclosure is worth the loss of the vault and their livelihoods.",
      "faction_ids": [
        "fac_heatkeepers",
        "fac_riggers_union",
        "fac_charter_office"
      ]
    }
  ]
}

