  ],
  "rules": [
    {
      "id": "rul_orbital_transfers",
      "statement": "Every vessel follows orbital mechanics; changing orbit costs propellant, time, or both, and no craft can make an instantaneous rendezvous.",
      "category": "physics"
    },
    {
      "id": "rul_light_delay",
      "statement": "Signals travel no faster than light, so distant ships and stations exchange messages with measurable delay.",
      "category": "physics"
    },
    {
      "id": "rul_sail_attitude",
      "statement": "A reflective sail produces useful thrust only when its orientation and illumination are controlled; a damaged or shadowed sail cannot provide reliable station-keeping.",
      "category": "technology"
    },
    {
      "id": "rul_heat_budget",
      "statement": "The yard must reject or store every unit of waste heat; unexplained power consumption eventually appears as a thermal imbalance.",
      "category": "technology"
    },
    {
      "id": "rul_charter_audit",
      "statement": "The charter requires each hull, mass transfer, and power connection to have a traceable entry; an unresolved discrepancy can suspend salvage operations.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_berths",
      "name": "First Berths Cut",
      "description": "The yard opened as a refit station for inner-system sail craft, with its shaded spine designed to buffer the sharp swings between sunlight and stored heat.",
      "era": "Founding years",
      "location_ids": [
        "loc_cinder_spindle",
        "loc_sail_cradle"
      ]
    },
    {
      "id": "evt_vault_gap",
      "name": "The Vault Interval",
      "description": "A power-balancing incident left a long blank in the Shadow Vault's maintenance archive. Officials called it a sensor failure; later crews found the junction seals newer than the record claimed.",
      "era": "Two decades before the audit",
      "location_ids": [
        "loc_shadow_vault"
      ]
    },
    {
      "id": "evt_hull_condemned",
      "name": "Condemned on Paper",
      "description": "A sail vessel was entered as scrapped and assigned to Ash Dock, but its cutting authorization was never countersigned. Its registry was closed anyway.",
      "era": "Recent cycle",
      "location_ids": [
        "loc_ash_dock",
        "loc_cinder_spindle"
      ]
    },
    {
      "id": "evt_power_anomaly",
      "name": "The Steady Draw",
      "description": "A rigger reconciling berth loads noticed a persistent current attributed to the condemned hull. Comparing it with the vault's heat traces revealed the same recurring pattern.",
      "era": "Audit approach",
      "location_ids": [
        "loc_ash_dock",
        "loc_shadow_vault"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_audit_clock",
      "name": "The Audit Clock",
      "description": "The Charter Office needs a clean ledger before auditors arrive; the Riggers' Compact needs time to inspect the hull without losing access to the berth. Any delay risks a shutdown, while any hurried declaration could erase the only evidence.",
      "faction_ids": [
        "fac_charter_office",
        "fac_riggers_union"
      ]
    },
    {
      "id": "cnf_heatkeepers_secret",
      "name": "A Circuit Kept Quiet",
      "description": "The Heatkeepers can explain the old thermal traces but risk exposing an unauthorized connection maintained across generations. The rigger needs their records; the crew must decide whether disclosure is worth the loss of the vault and their livelihoods.",
      "faction_ids": [
        "fac_heatkeepers",
        "fac_riggers_union",
        "fac_charter_office"
      ]
    }
  ]
}

response.output:
{
  "world_id": "wld_rainremembered",
  "name": "The Rainward Valleys",
  "description": "After the collapse of the old world, four valley towns survive by tending terraces, repairing salvaged hand-tools, and sharing seed. A seed-keeper's caravan must cross them before the last frost, carrying grain stock and seeking to mend the feud that split the seedway routes. Here, rain leaves faint mineral tracings on old stone: after a storm, careful readers can sometimes make out the patterns of crops grown there generations ago. The marks are imperfect, but they remind the towns that the land has recovered before—and may recover again.",
  "locations": [
    {
      "id": "loc_ashcombe",
      "name": "Ashcombe Terraces",
      "description": "A stepped hillside of ash-dark soil, rebuilt with stone walls and hand-carried compost. Its orchard keepers shelter the caravan, but the town's grain stores are thin."
    },
    {
      "id": "loc_morrowford",
      "name": "Morrowford",
      "description": "A shallow river crossing where old bridge timbers have been turned into footbridges and sluice gates. Rain tracings on the ford's stones show a long-vanished barley field."
    },
    {
      "id": "loc_bellwether",
      "name": "Bellwether Hollow",
      "description": "A sheltered town of root cellars and seed lofts beneath a ridge. Its people keep careful planting records, though they distrust travelers who ask about the sealed granary."
    },
    {
      "id": "loc_frostmere",
      "name": "Frostmere",
      "description": "The highest valley settlement, ringed with windbreaks and abandoned slate roofs. Its thaw-fed gardens are the last stop before the mountain pass, and the first hard frost comes early here."
    }
  ],
  "factions": [
    {
      "id": "fac_wayseed_caravan",
      "name": "The Wayseed Caravan",
      "description": "A moving fellowship of seed-keepers, pack handlers, and tool menders. They trade grain stock for safe passage and carry a living record of which seed varieties thrive in each valley.",
      "location_ids": [
        "loc_ashcombe",
        "loc_morrowford",
        "loc_bellwether",
        "loc_frostmere"
      ]
    },
    {
      "id": "fac_bellwether_ledgers",
      "name": "The Bellwether Ledger Council",
      "description": "Record keepers who guard the sealed granary and claim that only their town can decide how much seed is lent beyond its walls. Their books preserve both useful harvest notes and the names of those blamed for the old feud.",
      "location_ids": [
        "loc_bellwether"
      ]
    },
    {
      "id": "fac_fordwardens",
      "name": "The Fordwardens",
      "description": "Morrowford families who maintain the crossing and direct traffic along the river route. They will help the caravan, but refuse to open the upstream sluice until Bellwether acknowledges the harm done to their ancestors.",
      "location_ids": [
        "loc_morrowford"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_handpower",
      "statement": "All work depends on human or animal effort and salvaged hand-tools; no powered machinery remains in use.",
      "category": "technology"
    },
    {
      "id": "rul_seedviability",
      "statement": "Seed kept dry and cool can remain viable for years, but each planting must leave enough grain for the next season.",
      "category": "other"
    },
    {
      "id": "rul_raintracings",
      "statement": "After a strong rain, mineral stains may reveal old crop patterns on exposed stone, but they cannot show who planted them or when.",
      "category": "other"
    },
    {
      "id": "rul_routecustom",
      "statement": "A town may deny passage through its fields, but the river crossing and mountain pass remain shared routes by long-standing custom.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_routefeud",
      "name": "The Split Seedway",
      "description": "A disputed grain loan ended in a broken agreement between Bellwether and Morrowford. Each town closed its favored route, leaving smaller settlements isolated and dividing the valley's seed stores.",
      "era": "Three generations ago",
      "location_ids": [
        "loc_bellwether",
        "loc_morrowford"
      ]
    },
    {
      "id": "evt_firsttracings",
      "name": "The Marks After Rain",
      "description": "During a season of heavy storms, farmers noticed crop shapes appearing as mineral traces on the washed stones at Morrowford. They used the patterns to restore an old terrace planting, beginning a shared custom of comparing rain-marked ground.",
      "era": "The first recovery years",
      "location_ids": [
        "loc_morrowford",
        "loc_ashcombe"
      ]
    },
    {
      "id": "evt_windbreaks",
      "name": "Frostmere's Windbreak Oath",
      "description": "After an early freeze ruined the exposed gardens, Frostmere's households planted a ring of windbreak trees together and pledged to share cuttings with any valley that sent help before winter.",
      "era": "A generation ago",
      "location_ids": [
        "loc_frostmere"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_grainandpassage",
      "name": "The Locked Crossing",
      "description": "The caravan's grain stock could replenish Bellwether's stores, but the Fordwardens will not open the sluice route until the Ledger Council admits that its ancestors broke the original loan agreement. Waiting for an apology risks losing the mountain pass to frost; forcing the crossing could make the feud permanent.",
      "faction_ids": [
        "fac_wayseed_caravan",
        "fac_bellwether_ledgers",
        "fac_fordwardens"
      ]
    },
    {
      "id": "cnf_sealedreserve",
      "name": "The Granary's Last Measure",
      "description": "The Ledger Council says its sealed reserve must be kept for Bellwether's own planting, while the caravan argues that sharing a portion now could save every town's next harvest. Neither side knows whether the stored seed will stay viable through another winter.",
      "faction_ids": [
        "fac_wayseed_caravan",
        "fac_bellwether_ledgers"
      ]
    }
  ]
}

