response.output:
{
  "world_id": "wld_ashen_measure",
  "name": "The Ashen Measure",
  "description": "Beyond the final breath lies a country of counting-houses, where the dead wait not for judgment from a throne but for the orderly settling of their accounts. Its roads run between ink-black canals and hills of pale ash; every name is entered in a ledger, every obligation weighed against what a life gave and took. A junior scribe has found one soul entered under the column for debts owed by the living. The correction must pass through offices whose clerks guard their procedures as fiercely as their reputations, before the soul reaches the weighing floor. The world is solemn about loss and wry about bureaucracy: even eternity has queues, stamps, and appeals.",
  "locations": [
    {
      "id": "loc_silt_gate",
      "name": "Silt Gate",
      "description": "The arrival quay where ferrymen unload the newly dead into a receiving hall. Its gates are marked with tide lines rather than dates, since the canal rises whenever a forgotten name is spoken."
    },
    {
      "id": "loc_moth_archive",
      "name": "The Moth Archive",
      "description": "A vault of ledgers kept in drawers of cedar and bone. Pale moths feed only on erased sums, and their wing patterns preserve the last version of any entry they consume."
    },
    {
      "id": "loc_copper_countinghouse",
      "name": "Copper Counting-House",
      "description": "A red-roofed office built around a gigantic balance. Clerks there reconcile property, promises, and unpaid kindness, while the balance gives a small chime whenever a figure is honestly entered."
    },
    {
      "id": "loc_quiet_stairs",
      "name": "The Quiet Stairs",
      "description": "A long stair cut into a chalk cliff, connecting the counting-houses to the place of final weighing. Each landing holds a bench for appeals; no two benches face the same direction."
    },
    {
      "id": "loc_last_scale",
      "name": "The Last Scale",
      "description": "A circular chamber above a still lake, where an account is weighed and its bearer assigned a place in the far country. The scale has two pans, but the lake beneath it reflects three."
    }
  ],
  "factions": [
    {
      "id": "fac_quay_clerks",
      "name": "The Quay Clerks",
      "description": "Intake officials who record names at Silt Gate and insist that a neat first entry prevents untidy disputes later. Their ledgers are accurate, though they rarely ask who supplied the information.",
      "location_ids": [
        "loc_silt_gate"
      ]
    },
    {
      "id": "fac_mothkeepers",
      "name": "The Mothkeepers",
      "description": "Archive custodians who study the moths' wing marks to recover altered entries. They keep their findings private until a correction has a sponsor willing to risk a public hearing.",
      "location_ids": [
        "loc_moth_archive"
      ]
    },
    {
      "id": "fac_balance_office",
      "name": "The Office of Even Sums",
      "description": "Senior assessors who run the Copper Counting-House and defend the consistency of its measures. They fear that admitting one misfiled account will call every old judgment into question.",
      "location_ids": [
        "loc_copper_countinghouse",
        "loc_last_scale"
      ]
    },
    {
      "id": "fac_stair_petitioners",
      "name": "The Landing Petitioners",
      "description": "A loose fellowship of dead clerks, witnesses, and patient complainants who carry appeals up the Quiet Stairs. Their custom is to share one true memory at each landing, so no account is judged as if its bearer had been only a number.",
      "location_ids": [
        "loc_quiet_stairs"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_accounts_only",
      "statement": "The dead cannot return to life; only their accounts move between offices and places.",
      "category": "metaphysics"
    },
    {
      "id": "rul_ledger_record",
      "statement": "A soul cannot be weighed until its name and account appear in the central ledger.",
      "category": "social"
    },
    {
      "id": "rul_memory_witness",
      "statement": "A remembered deed may challenge a written sum only when a living witness or an archived mark supports it.",
      "category": "metaphysics"
    },
    {
      "id": "rul_moth_trace",
      "statement": "Moths consume erased figures but retain their shape in the pattern of their wings.",
      "category": "physics"
    },
    {
      "id": "rul_no_private_scale",
      "statement": "No official may alter a final weight alone; any correction requires a clerk from another house to countersign.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_three_pan_reflection",
      "name": "The Third Reflection",
      "description": "At the founding of the Last Scale, its builders saw a third pan in the lake's reflection and covered the water with slate. The reflected pan remains visible whenever an account has been placed in the wrong column.",
      "era": "Founding era",
      "location_ids": [
        "loc_last_scale"
      ]
    },
    {
      "id": "evt_moth_compact",
      "name": "The Moth Compact",
      "description": "After a purge of disputed records, archive keepers noticed that moths preserved traces of erased sums. They won the right to keep the insects and to submit their patterns as evidence, though not to interpret that evidence without a sponsor.",
      "era": "Era of Seals",
      "location_ids": [
        "loc_moth_archive",
        "loc_copper_countinghouse"
      ]
    },
    {
      "id": "evt_quiet_petition",
      "name": "The Quiet Petition",
      "description": "Dead petitioners once crowded the stair until the assessors agreed to benches and scheduled hearings. In exchange, petitioners vowed to bring one verifiable memory rather than a thousand pleas.",
      "era": "Current era",
      "location_ids": [
        "loc_quiet_stairs"
      ]
    }
