{
  "world_id": "wld_ice_and_coin",
  "name": "Ice and Coin",
  "description": "The market-fleet of Kestrel's Wake is lashed to a captured comet, its traders, pilots, and hired blades living among ice caverns and canvas-sailed hulls. As the comet swings toward its perihelion burn, a sealed star-map vanishes from the guild vault. The guild's factotum must hear rival claims and trace the theft before the heat drives the fleet apart. In this swashbuckling frontier, bargains carry more weight than flags, and a good tether can matter more than a good sword. One oddity shapes every voyage: the comet's deep ice records old impacts as bands of colored pressure-glass, and veteran navigators read those bands as a ledger of where the comet has been.",
  "locations": [
    {
      "id": "loc_crown_market",
      "name": "Crown Market",
      "description": "A crowded bazaar of stitched awnings and bridge-planks, wrapped around a ridge of blue ice. Merchant houses trade water, sailcloth, and passage while guild clerks settle claims at open-air tables."
    },
    {
      "id": "loc_guild_vault",
      "name": "The Sealed Vault",
      "description": "A pressure-locked chamber cut into the comet's coreward wall. Its doors bear wax seals from three rival guilds, and the missing star-map was kept in a coffer designed to reveal tampering."
    },
    {
      "id": "loc_tether_spindle",
      "name": "Tether Spindle",
      "description": "A spinning iron mast where cargo lines, ship tethers, and warning bells converge. Crews queue here to secure berths before the burn makes every loose line a hazard."
    },
    {
      "id": "loc_glass_strata",
      "name": "The Glass Strata",
      "description": "A narrow cavern striped with colored pressure-glass, each band left by an ancient impact. Navigators argue over its patterns; the oldest layers suggest the comet once crossed routes absent from every accepted chart."
    },
    {
      "id": "loc_sunward_docks",
      "name": "Sunward Docks",
      "description": "A chain of exposed ice piers facing the comet's coming heat. Sailmakers patch hullcloth here, while pilots test reaction plumes and prepare escape tethers for the scattered fleet."
    }
  ],
  "factions": [
    {
      "id": "fac_meridian_guild",
      "name": "Meridian Guild",
      "description": "The market's arbiters, bookkeepers, and bonded couriers. They insist the map's theft is an attack on every contract they have ever witnessed, but their vault seals bear marks from an internal inspection.",
      "location_ids": [
        "loc_crown_market",
        "loc_guild_vault"
      ]
    },
    {
      "id": "fac_red_canvas",
      "name": "Red Canvas Captains",
      "description": "A loose league of sail captains who tow the market between safe anchorages. They want the star-map found, yet fear the guild will use it to dictate every future route.",
      "location_ids": [
        "loc_tether_spindle",
        "loc_sunward_docks"
      ]
    },
    {
      "id": "fac_strata_keepers",
      "name": "Strata Keepers",
      "description": "Ice readers who maintain the pressure-glass caverns and preserve their impact records. They suspect the stolen map points to a hidden passage through the comet's old trajectory, a discovery that could end their custodianship.",
      "location_ids": [
        "loc_glass_strata",
        "loc_guild_vault"
      ]
    },
    {
      "id": "fac_scripless",
      "name": "The Scripless",
      "description": "Debtors, salvagers, and displaced families who live along the outer tethers. They distrust guild hearings and claim the map was sealed away to keep the fleet dependent on paid pilots.",
      "location_ids": [
        "loc_crown_market",
        "loc_tether_spindle"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_sail_motion",
      "statement": "Ships manoeuvre by sail, tether, and reaction plume; no energy weapons are used.",
      "category": "technology"
    },
    {
      "id": "rul_comet_burn",
      "statement": "Near perihelion, the comet's heated jets become erratic, and exposed vessels must either cut loose or risk being dragged off course.",
      "category": "physics"
    },
    {
      "id": "rul_pressure_glass",
      "statement": "Deep ice records major impacts as colored pressure-glass bands, but reading their sequence requires comparing several strata.",
      "category": "other"
    },
    {
      "id": "rul_tether_claim",
      "statement": "A crew that abandons a marked tether without witnesses forfeits its berth and cargo claim under market law.",
      "category": "social"
    },
    {
      "id": "rul_sealed_evidence",
      "statement": "Guild arbitration accepts a sealed object as evidence only when every recorded custodian can account for its seal.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_capture",
      "name": "The Comet Taken in Tow",
      "description": "Generations ago, stranded crews caught the comet with woven tow-lines and anchored their first shelters in its lee. The fleet grew around that desperate rescue.",
      "era": "Founding years",
      "location_ids": [
        "loc_tether_spindle",
        "loc_crown_market"
      ]
    },
    {
      "id": "evt_glass_discovery",
      "name": "The First Pressure Ledger",
      "description": "Ice readers found colored impact bands beneath the market and proved that the comet's scars could preserve a record older than any ship's log. The guild recognized their findings as navigational evidence.",
      "era": "Age of ledgers",
      "location_ids": [
        "loc_glass_strata"
      ]
    },
    {
      "id": "evt_map_sealed",
      "name": "The Chart Behind Three Seals",
      "description": "After a disputed expedition, the Meridian Guild locked a star-map in its vault and required three rival houses to witness the seals. No public account explains what route caused the dispute.",
      "era": "Seven cycles ago",
      "location_ids": [
        "loc_guild_vault",
        "loc_crown_market"
      ]
    },
    {
      "id": "evt_berth_strike",
      "name": "The Berth Strike",
      "description": "The Scripless blocked the tether queues until the captains recognized uncrewed family berths. The agreement held, but left the fleet divided over who may claim a safe line during a burn.",
      "era": "Last cycle",
      "location_ids": [
        "loc_tether_spindle",
        "loc_sunward_docks"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_missing_chart",
      "name": "The Map Without a Seal",
      "description": "The guild needs the star-map recovered before the burn, while the captains want its route made public and the Strata Keepers fear it exposes a secret buried in the ice. The factotum's verdict may decide whether the fleet shares one course or splits into competing claims.",
      "faction_ids": [
        "fac_meridian_guild",
        "fac_red_canvas",
        "fac_strata_keepers"
      ]
    },
    {
      "id": "cnf_last_berths",
      "name": "The Last Safe Tethers",
      "description": "There are fewer protected berths than ships willing to risk the comet's heat. The Scripless demand that families be secured first; captains argue that vessels carrying the market's water stores must take priority.",
      "faction_ids": [
        "fac_red_canvas",
        "fac_scripless",
        "fac_meridian_guild"
      ]
    },
    {
      "id": "cnf_ice_rights",
      "name": "Who Owns the Scars",
      "description": "The Strata Keepers say the pressure-glass record belongs to everyone and must be read in full. The guild calls it a protected navigational asset, while the Scripless suspect the record can prove their families were cheated of passage.",
      "faction_ids": [
        "fac_strata_keepers",
        "fac_meridian_guild",
        "fac_scripless"
      ]
    }
  ]
}

