response.output:
{
  "world_id": "wld_saffron_tide",
  "name": "The Saffron Tide",
  "description": "At the western edge of the Indian Ocean, the walled port of Namarat measures its fortunes by the monsoon. In this sumptuous, tense world of spice warehouses, rain-darkened stone, and crowded anchorages, a harbour scribe must reconcile three foreign envoys' rival claims to the first sailing slot before the seasonal wind turns. The port's order rests on a fragile custom: each claim is recorded not only in ink but in a strip of sailcloth, whose knots and stains testify to when and where it was presented. Yet a missing cloth and a disputed tide mark threaten to make the ledger itself an instrument of betrayal. Namarat's fortunes depend on ships leaving in the right season, and every delay risks cargo, alliances, and lives.",
  "locations": [
    {
      "id": "loc_saffron_quay",
      "name": "Saffron Quay",
      "description": "The deepwater landing beneath Namarat's seaward wall, where arriving ships unload pepper, indigo, porcelain, and horses. Mooring places are assigned by tide and season; a carved pillar bears the old marks showing how high the water stood on notable departure days."
    },
    {
      "id": "loc_ledger_house",
      "name": "House of the Open Ledger",
      "description": "A shaded customs hall where harbour scribes copy cargo declarations and preserve claims to sailing order. Bundles of sailcloth strips hang above the desks, each marked with knotted thread, ink, or a witness's seal."
    },
    {
      "id": "loc_rain_gate",
      "name": "Rain Gate",
      "description": "A narrow passage between the port and its inland caravan road. During heavy rains, runoff crosses its stone floor in a shallow stream, and merchants gather beneath the gate's overhang to bargain while ox carts wait."
    },
    {
      "id": "loc_windward_shrine",
      "name": "Shrine of the Turning Gust",
      "description": "A small sea-facing sanctuary on a rocky rise above the anchorage. Its attendants keep a public record of wind direction, cloud bands, and the first rain, using palm-leaf sheets whose dated entries are consulted by captains and officials alike."
    }
  ],
  "factions": [
    {
      "id": "fac_harbour_scribes",
      "name": "The Quill and Cord",
      "description": "Namarat's clerks, witnesses, and seal-keepers, charged with recording cargo and fixing the order of departure. Their authority depends on the belief that every claim has a traceable place in the ledger and a matching sailcloth token.",
      "location_ids": [
        "loc_ledger_house",
        "loc_saffron_quay"
      ]
    },
    {
      "id": "fac_khorasani_envoys",
      "name": "The Khorasani Envoy House",
      "description": "Representatives of a powerful northern court who claim their laden vessel was promised the first sailing slot in return for a harbor levy paid before the rains. They carry a sealed receipt whose date appears to have been altered.",
      "location_ids": [
        "loc_ledger_house",
        "loc_rain_gate"
      ]
    },
    {
      "id": "fac_zanj_coalition",
      "name": "The Zanj Sea League",
      "description": "Captains and merchants from the African coast whose ships bring ivory, mangrove timber, and gold. They insist that an earlier promise was made at the quay before witnesses, and that their sailcloth token vanished from the customs hall.",
      "location_ids": [
        "loc_saffron_quay",
        "loc_windward_shrine"
      ]
    },
    {
      "id": "fac_gujarati_guild",
      "name": "The Guild of the Painted Hull",
      "description": "A western Indian merchant guild whose convoy carries dyed cloth and rice. Its envoy argues that the first slot belongs to the vessel best prepared for the coming wind, and presents a shrine record as proof that the season's turning is closer than the harbor officials admit.",
