response.output:
{
  "world_id": "wld_wickmere_parish",
  "name": "The Wickmere Bounds",
  "description": "Wickmere is a remote parish of peat, standing water, and low stone walls, where four settlements cling to a strip of firm ground. Its wall lanterns are tended every night by hand. The parish holds that at least one must remain alight: if every flame fails before dawn, the boundary stones shift, and a house or field may be counted as part of the moor by morning. A new lamplighter inherits the rounds and discovers that the ledger recording last winter's lit nights has a page cut out. In the gap lies the only night the keepers cannot agree to remember. Here, custom is both shelter and threat, and the smallest light can make a dangerous claim.",
  "locations": [
    {
      "id": "loc_wickmere_green",
      "name": "Wickmere Green",
      "description": "The parish's close-packed hamlet, set around a well and a stone meeting house. A wall lantern hangs at each lane mouth; residents watch their flames from shuttered windows, though few admit to counting them."
    },
    {
      "id": "loc_drowned_causey",
      "name": "The Drowned Causey",
      "description": "A raised stone path across the peat pools, marked by iron hooks and lantern niches. The water below sometimes reflects a light that has not yet been lit."
    },
    {
      "id": "loc_vestry_loft",
      "name": "The Vestry Loft",
      "description": "A cramped room above the meeting house where lamp oil, trimmed wicks, and the parish ledger are kept. Its shelves bear a clean, pale gap where a page was neatly removed."
    },
    {
      "id": "loc_black_sedge",
      "name": "Black Sedge Wall",
      "description": "The last boundary wall before open moor, its stones sunk at odd angles into black peat. A chain of lantern brackets follows it, ending at a sealed gate no one claims to have built."
    }
  ],
  "factions": [
    {
      "id": "fac_lampwardens",
      "name": "The Lampwardens",
      "description": "Keepers chosen from parish households to tend the wall lanterns and record each night's flames. They disagree over whether the missing ledger page conceals a failure or a deliberate act.",
      "location_ids": [
        "loc_wickmere_green",
        "loc_vestry_loft",
        "loc_black_sedge"
      ]
    },
    {
      "id": "fac_moorwardens",
      "name": "The Moorwardens",
      "description": "A handful of peat-cutters and path-menders who know the drowned ground by touch. They believe the lantern chain marks an old agreement, not a defense, and oppose repairs that would extend it.",
      "location_ids": [
        "loc_drowned_causey",
        "loc_black_sedge"
      ]
    },
    {
      "id": "fac_parish_council",
      "name": "The Parish Table",
      "description": "Elders who settle disputes in the meeting house and ration lamp oil. They preserve the rule of the lights while withholding what they know about last winter.",
      "location_ids": [
        "loc_wickmere_green",
        "loc_vestry_loft"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_one_wick",
      "statement": "Before dawn, at least one wall lantern must remain alight; if all are dark together, the parish boundary changes by morning.",
      "category": "metaphysics"
    },
    {
      "id": "rul_flame_claim",
      "statement": "A lantern lit at a boundary bracket marks the ground beneath it as belonging to the parish until that flame goes out.",
      "category": "metaphysics"
    },
    {
      "id": "rul_recorded_nights",
      "statement": "The keepers record every night and every lantern that burns; an unrecorded night cannot be settled by parish vote.",
      "category": "social"
    },
    {
      "id": "rul_handwork",
      "statement": "All travel, hauling, and lighting depend on human or animal labor; there are no engines, and every lamp must be tended by hand.",
      "category": "technology"
    },
    {
      "id": "rul_moor_reflection",
      "statement": "Still water on the moor reflects lanterns that have not yet been lit, but never shows who will light them.",
      "category": "metaphysics"
    }
  ],
  "history": [
    {
      "id": "evt_first_chain",
      "name": "The First Chain",
      "description": "Parish memory says the wall lanterns were set after a winter when the causey vanished beneath the peat. The account names no builder, only the households that supplied oil.",
      "era": "Before the parish books",
      "location_ids": [
        "loc_drowned_causey",
        "loc_black_sedge"
      ]
    },
    {
      "id": "evt_missing_night",
      "name": "The Missing Night",
      "description": "Last winter, the keepers' ledger recorded a run of lit nights, but one page was cut cleanly from its binding. The surviving entries on either side disagree about how many lanterns were burning.",
      "era": "Last winter",
      "location_ids": [
        "loc_vestry_loft",
        "loc_black_sedge"
      ]
    },
    {
      "id": "evt_new_keeper",
      "name": "A New Round",
      "description": "With the old lamplighter gone, the parish assigned the rounds to a newcomer. On the first night, every flame held steady except the one beside the sealed gate, where the wick burned down without shortening.",
      "era": "Present",
      "location_ids": [
        "loc_wickmere_green",
        "loc_black_sedge"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_ledger_truth",
      "name": "The Unentered Night",
      "description": "The Lampwardens want the missing page restored, the Parish Table wants the old account left undisturbed, and the Moorwardens want the lantern chain shortened. The new lamplighter must decide what to record before another night passes without a trustworthy count.",
      "faction_ids": [
        "fac_lampwardens",
        "fac_moorwardens",
        "fac_parish_council"
      ]
    }
  ]
}

